def transform(grid):
    """Compare aligned rows in two separated panels; mark only the longer panel's extra foreground cells."""
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in grid]
    bands, start = [], None
    for r, on in enumerate(active + [False]):
