    for k in range(min(b-a, d-c)):
        r1, r2 = a+k, c+k
        cols1 = [j for j, v in enumerate(grid[r1]) if v != bg]
        cols2 = [j for j, v in enumerate(grid[r2]) if v != bg]
        if not cols1 or not cols2:
            continue
        e1, e2 = max(cols1), max(cols2)
        if e1 > e2:
            for j in range(e2+1, e1+1):
                if grid[r1][j] != bg and grid[r2][j] == bg:
                    out[r2][j] = 1
        elif e2 > e1:
            for j in range(e1+1, e2+1):
                if grid[r2][j] != bg and grid[r1][j] == bg:
                    out[r1][j] = 1
    return out
