    end2 = max(j for r in range(c,d) for j,v in enumerate(grid[r]) if v != bg)
    # One panel is the short source; extend its row-wise suffix from the long panel.
    if end1 < end2:
        short_start, long_start = a, c
    elif end2 < end1:
        short_start, long_start = c, a
    else:
        return out
