        cs = [j for j,v in enumerate(grid[rs]) if v != bg]
        cl = [j for j,v in enumerate(grid[rl]) if v != bg]
        if not cs or not cl:
            continue
        es, el = max(cs), max(cl)
        for j in range(es+1, el+1):
            if grid[rl][j] != bg:
                out[rs][j] = 1
    return out
