        return out
    (a, b), (c, d) = bands[:2]
    w = len(grid[0])
    for k in range(min(b-a, d-c)):
        rt, rb = a+k, c+k
        top, bot = grid[rt], grid[rb]
        # Align the two copies by the longest exact left-to-right prefix (small shifts).
        candidates = []
        for shift in range(-3, 4):  # bottom column = top column + shift
            n = 0
            while 0 <= n < w and 0 <= n+shift < w and top[n] == bot[n+shift]:
                n += 1
            candidates.append((n, -abs(shift), shift))
        _, _, shift = max(candidates)
        # Measure rightmost foreground in the shared coordinate system.
        tcols = [j for j,v in enumerate(top) if v != bg]
        bcols = [j-shift for j,v in enumerate(bot) if v != bg]
        et = max(tcols, default=-1)
        eb = max(bcols, default=-1)
        if et > eb:
            # Top has the right overhang; mark its unmatched foreground on the lower copy.
            for x in range(max(0, eb+1), min(w, et+1)):
                j = x + shift
                if 0 <= j < w and top[x] != bg and bot[j] == bg:
                    out[rb][j] = 1
        elif eb > et:
            # Bottom has the right overhang; mark it on the upper copy.
            for x in range(max(0, et+1), min(w, eb+1)):
                j = x + shift
                if 0 <= j < w and bot[j] != bg and top[x] == bg:
                    out[rt][x] = 1
        else:
            # Equal extents: mark differences in the top copy only after the common prefix.
            common = 0
            while common < w and 0 <= common+shift < w and top[common] == bot[common+shift]:
                common += 1
            for x in range(common, w):
                j = x + shift
                if 0 <= j < w and top[x] != bot[j]:
                    out[rt][x] = 1
    return out
