        return out
    (a, b), (c, d) = bands[:2]
    n, w = min(b-a, d-c), len(grid[0])
    # Find horizontal alignment of the paired panels, with shift = lower_col - upper_col.
    scores = []
    for shift in range(-4, 5):
        matches = total = 0
        for k in range(n):
            for x in range(w):
                y = x + shift
                if 0 <= y < w:
                    total += 1
                    matches += grid[a+k][x] == grid[c+k][y]
        scores.append((matches / total if total else 0, -abs(shift), shift))
