def transform(grid):
    """Align the two separated panels, then mark the continuation of the longer panel on the shorter one."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in grid]
    bands, start = [], None
    for r, on in enumerate(active + [False]):
        if on and start is None:
            start = r
        elif not on and start is not None:
            bands.append((start, r))
            start = None
    if len(bands) < 2:
        return out
    (a,b),(c,d)=bands[:2]
    n=min(b-a,d-c)
    def ext(lo,hi):
        return max((j for r in range(lo,hi) for j,v in enumerate(grid[r]) if v!=bg),default=-1)
    e1,e2=ext(a,b),ext(c,d)
    # Align paired rows by their shared visible pattern, ignoring the cut-off tail.
    shifts=[]
    for s in range(-3,4): # lower column = upper column + s
        matches=total=0
        upto=min(e1, e2-s)
        for k in range(n):
            for x in range(max(0,-s),min(w,upto+1)):
                y=x+s
                if 0<=y<=e2:
                    total+=1
                    matches += (grid[a+k][x]==grid[c+k][y])
        shifts.append((matches/total if total else 0, -abs(s), s))
    shift=max(shifts)[2]
    # Compare panels in common coordinates. The smaller right extent is truncated.
    lower_extent_in_upper = e2-shift
    if e1 > lower_extent_in_upper:
        # Upper panel continues farther; place its unseen tail in the lower panel.
        for k in range(n):
