            start = r
        elif not on and start is not None:
            bands.append((start, r))
            start = None
    if len(bands) < 2:
        return out
    (a,b),(c,d)=bands[:2]
    n, w = min(b-a,d-c), len(grid[0])
    def rightmost(lo,hi):
        return max((j for r in range(lo,hi) for j,v in enumerate(grid[r]) if v!=bg),default=-1)
    ea, eb = rightmost(a,b), rightmost(c,d)
    # Align the two repeated panels. The matching prefix determines their horizontal offset.
    scores=[]
    for shift in range(-5,6):  # second-panel column = first-panel column + shift
        matches=total=0
        for k in range(n):
            for x in range(w):
                y=x+shift
                if 0<=y<w and x<=ea and y<=eb:
                    matches += grid[a+k][x] == grid[c+k][y]
                    total += 1
        scores.append((matches/total if total else 0, -abs(shift), shift))
    shift=max(scores)[2]
    # Extend the panel with the shorter aligned right extent by marking the
    # longer panel's extra foreground pixels in the corresponding blank cells.
    eb_aligned=eb-shift
    if ea>eb_aligned:
        for k in range(n):
            for x in range(max(0,eb_aligned+1), min(ea+1,w)):
                y=x+shift
                if 0<=y<w and grid[a+k][x]!=bg and grid[c+k][y]==bg:
                    out[c+k][y]=1
    elif eb_aligned>ea:
        for k in range(n):
            for x in range(max(0,ea+1), min(eb_aligned+1,w)):
                y=x+shift
                if 0<=y<w and grid[c+k][y]!=bg and grid[a+k][x]==bg:
                    out[a+k][x]=1
    return out
